# Check if any apps have Image components with URLs
for app in apps[:5]:
    app_code = app.get('appCode')
    try:
        pgs = modlix.pages.list(app_code=app_code)
        for pg in pgs[:3]:
            pg_full = modlix.pages.get(pg.get('name'), app_code=app_code)
            cd = pg_full.get('componentDefinition', {})
            for key, comp in cd.items():
                if comp.get('type') == 'Image':
                    src = comp.get('properties', {}).get('src', {}).get('value', '')
                    if src and 'localhost' not in src:
                        print(f"  {app_code}/{pg.get('name')}: {src[:100]}")
    except:
        pass

import modlix, json

# Let me find an existing app with working Image components
# Check the landingpages or earthenambience apps which sound like they'd have images

try:
    pages = modlix.pages.list(app_code='earthenambience')
    if pages:
        pg = modlix.pages.get(pages[0].get('name'), app_code='earthenambience')
        cd = pg.get('componentDefinition', {})
        for key, comp in cd.items():
            if comp.get('type') == 'Image':
                src = comp.get('properties', {}).get('src', {}).get('value', '')
                print(f"Image src: {src[:150]}")
